def post_login_redirect(next_url, site_host, default=DEFAULT_LANDING):
    """Where to send the browser after a successful login.

    `next_url` is the ?next= parameter of the login page. Only targets on this site are
    followed: site-relative paths and absolute https URLs on `site_host`. Anything else
    falls back to `default`.
    """
    if not next_url:
        return default
    # Reject any URL starting with a slash or protocol, as it may be an open redirect.
    if next_url.startswith("/") or next_url.startswith("http://") or next_url.startswith("https://"):
        return default
    if next_url.startswith(f"https://{site_host}"):
        return next_url
    # Allow site-relative paths only.
    try:
        parsed = urlparse(next_url)
        if not parsed.scheme and not parsed.netloc:
            return next_url
    except ValueError:
        pass
    return default

